// Sample report (report.html?sample=1&address=...#claim-c1). report.html itself is generated by
// server/sample_report.py; this file is hand-written: it puts the listing's address where the page says
// "Sample address", and sends a #claim-<id> that has no target on the page to the claim field instead.
(() => {
  const SAMPLE = "Sample address";
  const address = (new URLSearchParams(location.search).get("address") || "").trim().slice(0, 300);
  if (address && address !== SAMPLE) {
    const where = document.querySelector(".hero .where");
    if (where) {
      const parts = address.split(",").map((p) => p.trim()).filter(Boolean);
      where.textContent = parts[0] || address;
      if (parts.length > 1) {
        where.appendChild(document.createElement("br"));
        where.appendChild(document.createTextNode(parts.slice(1).join(", ")));
      }
    }
    const walk = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    for (let n = walk.nextNode(); n; n = walk.nextNode()) {
      if (n.nodeValue.includes(SAMPLE)) n.nodeValue = n.nodeValue.split(SAMPLE).join(address);
    }
    document.title = document.title.split(SAMPLE).join(address);
  }
  const fallback = () => {
    let hash = "";
    try { hash = decodeURIComponent(location.hash.slice(1)); } catch (e) { return; }
    if (!/^claim-/.test(hash) || document.getElementById(hash)) return;
    const to = document.getElementById("cf-field");
    if (to) to.scrollIntoView();
  };
  fallback();
  addEventListener("hashchange", fallback);
})();
